# Try using ILP with OR-Tools or PuLP
# Let's try with a constraint programming approach using python-constraint or ortools

try:
    from ortools.sat.python import cp_model
    print("OR-Tools available")
except:
    print("OR-Tools not available")

try:
    import pulp
    print("PuLP available")
except:
    print("PuLP not available")

from pysat.solvers import Glucose4

N_V = 18
M = 33  # number of edges
N_L = M + 1  # labels 0..33

edges = []
for g in range(6):
    v0, v1, v2 = 3*g, 3*g+1, 3*g+2
    edges += [(v0,v1),(v0,v2),(v1,v2)]
for g in range(5):
    for i in range(3):
        edges.append((3*g+i, 3*(g+1)+i))

assert len(edges) == M

def xvar(v, l):
    # vertex v (0..17) gets label l (0..33)
    return v * N_L + l + 1  # 1-indexed

max_xvar = N_V * N_L  # = 18*34 = 612

def aux_var(e, d):
    # edge e (0..32) has difference d (1..33)
    return max_xvar + e * M + d  # d in 1..M

max_aux = max_xvar + M * M  # = 612 + 33*33 = 612 + 1089 = 1701

clauses = []

# 1. Each vertex gets exactly one label
for v in range(N_V):
    # At least one
    clauses.append([xvar(v, l) for l in range(N_L)])
    # At most one (pairwise)
    for l1 in range(N_L):
        for l2 in range(l1+1, N_L):
            clauses.append([-xvar(v, l1), -xvar(v, l2)])

# 2. Each label used at most once
for l in range(N_L):
    for v1 in range(N_V):
        for v2 in range(v1+1, N_V):
            clauses.append([-xvar(v1, l), -xvar(v2, l)])

print(f"After vertex/label constraints: {len(clauses)} clauses")

# 3. Edge difference implications
# x(u,a) AND x(v,b) => aux(e, |a-b|) for |a-b| >= 1
for ei, (u, v) in enumerate(edges):
    for a in range(N_L):
        for b in range(N_L):
            d = abs(a - b)
            if d >= 1:
                clauses.append([-xvar(u,a), -xvar(v,b), aux_var(ei, d)])

print(f"After implication clauses: {len(clauses)}")

# 4. Each edge has at least one diff (OR over d)
for ei in range(M):
    clauses.append([aux_var(ei, d) for d in range(1, M+1)])

# 5. At most one edge per diff value
for d in range(1, M+1):
    for e1 in range(M):
        for e2 in range(e1+1, M):
            clauses.append([-aux_var(e1, d), -aux_var(e2, d)])

print(f"After all constraints: {len(clauses)} clauses, max_var={max_aux}")

# Solve with Glucose4
solver = Glucose4()
for clause in clauses:
    solver.add_clause(clause)

print("Solving...")
result = solver.solve()
print(f"Result: {'SAT' if result else 'UNSAT'}")

if result:
    model = solver.get_model()
    labels = [None] * N_V
    for v in range(N_V):
        for l in range(N_L):
            if xvar(v, l) in model or (xvar(v,l) > 0 and model[xvar(v,l)-1] > 0):
                labels[v] = l
                break
    print(f"Labels: {labels}")
